// Compile-time assertion that grabberImpl satisfies sdk.MetadataSource (the one
// capability interface this plugin ships). The sdk.MetadataSourcePlugin adapter
// forwards the four unary RPCs here. Mirrors plugins/image-enricher/enricher.go.
var _ sdk.MetadataSource = (*grabberImpl)(nil)

// defaultDataDir mirrors the core's MELLIFERA_DATA_DIR default (cmd/mellifera).
const defaultDataDir = "./data"

// grabberImpl is the server-side MetadataSource capability for frame-grabber
// (serials-library D3). STATELESS between RPCs per document. Match self-selects
// video documents carrying an absolute path (a serial-record document —
// the series level — never applies); Convert invokes the system ffmpeg
// subprocess (os/exec arg-slice ONLY, never a shell) under a bounded timeout,
// seeking an explicit query seek_seconds when present (the stop-position
// re-grab), else min(default seek, a fraction of the probe-reported
// duration), and writes a single JPEG frame under <dataDir>/thumbs; Merge
// writes ONLY sources["frame-grabber"] — the thumbnail PATH, never a BLOB.
// The core stamps _provenance/_view authoritatively (INV-namespace-write).
type grabberImpl struct {
	sdk.UnsupportedSearch               // the interactive search pair: unsupported (identify-match-override)
	ffmpegPath            string        // ffmpeg binary to invoke (default "ffmpeg")
	dataDir               string        // thumbs root (MELLIFERA_DATA_DIR semantics)
	seek                  time.Duration // default seek into the file (default 300s)
	grabTimeout           time.Duration // per-grab ffmpeg deadline (default 30s)
}

// newGrabber fills the zero-value knobs with the shipped defaults.
func newGrabber(dataDir string) *grabberImpl {
	return &grabberImpl{
		ffmpegPath:  "ffmpeg",
		dataDir:     dataDir,
		seek:        defaultSeek,
		grabTimeout: grabTimeout,
	}
}

// Match decides whether this document is an episode frame-grab applies to:
// ONLY episode documents carrying a video absolute path. A serial-record
// document (the series level, directory- or file-backed) never applies — its
// parsed carries the serial-record marker, which no episode has (design.md
// §Interfaces §1-2). No I/O — a non-episode document is skipped (not an error).
func (*grabberImpl) Match(_ context.Context, req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	f := req.GetItem().GetParsed().GetFields()
	if f["serial_record"].GetBoolValue() {
		return &metadatav1.MatchResult{Applies: false, Reason: "series document, not an episode"}, nil
	}
	abs := f["absolute_path"].GetStringValue()
	if abs == "" {
		return &metadatav1.MatchResult{Applies: false, Reason: "no video absolute path"}, nil
	}
	q := map[string]any{
		"absolute_path": abs,
	}
	if rp := f["relative_path"].GetStringValue(); rp != "" {
		q["relative_path"] = rp
	}
	if srel := f["series_relative_path"].GetStringValue(); srel != "" {
		q["series_relative_path"] = srel
	}
	// The probe-reported duration is surfaced by the core into parsed
	// (probe_duration_seconds) when the document carries a probe — it clamps
	// the seek so short files still yield a frame.
	if d := f["probe_duration_seconds"].GetNumberValue(); d > 0 {
		q["probe_duration_seconds"] = d
	}
	query, _ := structpb.NewStruct(q)
	return &metadatav1.MatchResult{
		Applies:    true,
		Query:      query, // the file location becomes the chain's query
		Confidence: 1.0,
		Reason:     "episode with video absolute path",
	}, nil
}

// BuildRequest returns an empty RequestSpec: the local ffmpeg "fetch" is the
// subprocess run done in Convert (no external fetch). Mirrors image-enricher.
func (*grabberImpl) BuildRequest(_ context.Context, _ *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{Spec: &metadatav1.RequestSpec{}}, nil
}

// Convert grabs one frame from the episode video at Query.absolute_path and
// returns the thumbnail PATH as the namespace (never a BLOB). On any ffmpeg
// failure (missing binary / non-zero exit / timeout / unwritable output) it
// returns EMPTY metadata + a Warning — a soft-fail, NOT a gRPC error — flowing
// into the shipped no_data ledger cooldown. ONLY a cancelled context is a hard
// failure (returned as an error; the core's B7 path owns it).
func (g *grabberImpl) Convert(ctx context.Context, req *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	if err := ctx.Err(); err != nil {
		return nil, err // already cancelled: hard, before any work
	}
	q := req.GetQuery().GetFields()
	abs := q["absolute_path"].GetStringValue()
	rel := q["relative_path"].GetStringValue()
	seriesRel := q["series_relative_path"].GetStringValue()
	if seriesRel == "" {
		seriesRel = rel // file-backed episodes carry their own path as the series identity
	}
	seek := resolveSeek(g.seek, q)
	out := thumbPath(g.dataDir, seriesRel, rel)
	warning := grabFrame(ctx, g.ffmpegPath, abs, out, seek, g.grabTimeout)
	// The parent context cancelling mid-grab is the ONLY hard failure; every
	// other grabFrame outcome is a per-source warning (soft-fail).
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	result := &metadatav1.ConvertResult{}
	if warning == "" {
		st, _ := structpb.NewStruct(map[string]any{"thumbnail_path": out})
		result.Metadata = st
		result.Provenance = provenanceHints(st)
	} else {
		result.Warnings = []string{warning}
	}
	return result, nil
}

// Merge writes ONLY the sources.<plugin_id> namespace ("frame-grabber"). The
// plugin never touches _provenance/_view/_stages; the returned View bindings
// are a proposal the core recomputes authoritatively. Verbatim mirror of
// image-enricher's Merge (only pluginID differs).
func (*grabberImpl) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	id := req.GetPluginId()
	if id == "" {
		id = pluginID
	}
	meta := map[string]any{}
	if req.GetIncoming() != nil {
		meta = req.GetIncoming().AsMap()
	}
	data, _ := structpb.NewStruct(map[string]any{
		"sources": map[string]any{id: meta},
	})
	view := make([]*commonv1.ViewBinding, 0, len(meta))
	for field := range meta {
		view = append(view, &commonv1.ViewBinding{FieldPath: field, Source: id, Reason: "priority"})
	}
	return &metadatav1.MergeResult{
		Document: &commonv1.MediaDocument{Data: data},
		View:     view,
	}, nil
}

// resolveSeek derives the grab offset from the query (continue-nextup-media
// D-4/D-5): an explicit seek_seconds (the stop-position re-grab) replaces the
// configured default; a positive probe duration then clamps the result to
// seekDurationFraction of it — an override past EOF still lands on a real
// frame, and a short file still yields one at all. A non-positive or absent
// override never widens the seek.
func resolveSeek(def time.Duration, q map[string]*structpb.Value) time.Duration {
	seek := def
	if v := q["seek_seconds"].GetNumberValue(); v > 0 {
		seek = time.Duration(v * float64(time.Second))
	}
	if d := q["probe_duration_seconds"].GetNumberValue(); d > 0 {
		if clamped := time.Duration(d * float64(time.Second) * seekDurationFraction); clamped < seek {
			seek = clamped
		}
	}
	return seek
}

// thumbPath mints the deterministic thumbnail location per the design's path
// scheme: <dataDir>/thumbs/<sha16(series relative path)>/<sha16(episode
// relative path)>.jpg — sha16 being the first 16 lowercase hex chars of sha256
// over the raw path bytes (non-ASCII names hash over UTF-8 verbatim; the name
// itself is never mangled into the path).
func thumbPath(dataDir, seriesRel, episodeRel string) string {
	return filepath.Join(dataDir, "thumbs", sha16(seriesRel), sha16(episodeRel)+".jpg")
}

func sha16(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])[:16]
}

// provenanceHints builds the per-field provenance hint map the core merges over
// its authoritative _provenance stamp. Mirrors image-enricher.
func provenanceHints(meta *structpb.Struct) map[string]*commonv1.Provenance {
	fields := meta.GetFields()
	out := make(map[string]*commonv1.Provenance, len(fields))
	fetched := timestamppb.Now()
	for field := range fields {
		out[field] = &commonv1.Provenance{
			PluginId:      pluginID,
			PluginVersion: pluginVersion,
			FetchedAt:     fetched,
		}
	}
	return out
}
